class FilaBone(val ptr: Int) {
    val unitQuaternion: FilaQuat get() = FilaQuat(ptr + 0)
    val translation: FilaFloat3 get() = FilaFloat3(ptr + 16)
    var reserved: Float get() = fila.getF32(ptr + 28); set(value) { fila.setF32(ptr + 28, value) }
    companion object {
        const val SIZE = 32
        const val unitQuaternion = 0
        const val translation = 16
        const val reserved = 28
    }
}

class FilaBox(val ptr: Int) {
    var centerX: Float get() = fila.getF32(ptr + 0); set(value) { fila.setF32(ptr + 0, value) }
    var centerY: Float get() = fila.getF32(ptr + 4); set(value) { fila.setF32(ptr + 4, value) }
    var centerZ: Float get() = fila.getF32(ptr + 8); set(value) { fila.setF32(ptr + 8, value) }
    var halfExtentX: Float get() = fila.getF32(ptr + 12); set(value) { fila.setF32(ptr + 12, value) }
    var halfExtentY: Float get() = fila.getF32(ptr + 16); set(value) { fila.setF32(ptr + 16, value) }
    var halfExtentZ: Float get() = fila.getF32(ptr + 20); set(value) { fila.setF32(ptr + 20, value) }
    companion object {
        const val SIZE = 24
        const val centerX = 0
        const val centerY = 4
        const val centerZ = 8
        const val halfExtentX = 12
        const val halfExtentY = 16
        const val halfExtentZ = 20
    }
}

class FilaEngineConfig(val ptr: Int) {
    var commandBufferSizeMB: Int get() = fila.getI32(ptr + 0); set(value) { fila.setI32(ptr + 0, value) }
    var perRenderPassArenaSizeMB: Int get() = fila.getI32(ptr + 4); set(value) { fila.setI32(ptr + 4, value) }
