    var perFrameCommandsSizeMB: Int get() = fila.getI32(ptr + 16); set(value) { fila.setI32(ptr + 16, value) }
    var jobSystemThreadCount: Int get() = fila.getI32(ptr + 20); set(value) { fila.setI32(ptr + 20, value) }
    var disableParallelShaderCompile: Boolean get() = fila.getBool(ptr + 24); set(value) { fila.setBool(ptr + 24, value) }
    var stereoscopicType: Int get() = fila.getI32(ptr + 28); set(value) { fila.setI32(ptr + 28, value) }
    var stereoscopicEyeCount: Int get() = fila.getU8(ptr + 32); set(value) { fila.setU8(ptr + 32, value) }
    var resourceAllocatorCacheSizeMB: Int get() = fila.getI32(ptr + 36); set(value) { fila.setI32(ptr + 36, value) }
    var resourceAllocatorCacheMaxAge: Int get() = fila.getU8(ptr + 40); set(value) { fila.setU8(ptr + 40, value) }
    var disableHandleUseAfterFreeCheck: Boolean get() = fila.getBool(ptr + 41); set(value) { fila.setBool(ptr + 41, value) }
    var preferredShaderLanguage: Int get() = fila.getI32(ptr + 44); set(value) { fila.setI32(ptr + 44, value) }
